HERO_STR_STATIC(hero_str_684dddec, "# The Heroes library \342\200\224 Tier 2 of design.md \302\2471.11, written in Heroes itself.");
HERO_STR_STATIC(hero_str_23, "#");
HERO_STR_STATIC(hero_str_34c085c6, "# This file is compiled with every program. It is not on disk beside the");
HERO_STR_STATIC(hero_str_291d1809, "# compiler: it is `include_str!`d into the binary, so there is no discovery, no");
HERO_STR_STATIC(hero_str_3d72825e, "# `$HEROES_LIBRARY`, and no decoy \342\200\224 clang cannot type-check Heroes source, so a");
HERO_STR_STATIC(hero_str_36471c97, "# file here would have no analogue of the runtime's `_Static_assert` guarding it");
HERO_STR_STATIC(hero_str_774d6eda, "# (panel 028 R3).");
HERO_STR_STATIC(hero_str_7821ec6d, "# Rules for anything added here:");
HERO_STR_STATIC(hero_str_6b1a4e8f, "#   - it declares a name from the built-in inventory and nothing else. A helper");
HERO_STR_STATIC(hero_str_38410af1, "#     outside that table would take a name a user program is entitled to;");
HERO_STR_STATIC(hero_str_4ec045c7, "#   - it is ordinary Heroes, checked by the ordinary rules. That is the whole");
HERO_STR_STATIC(hero_str_639af8a4, "#     claim of Tier 2, and \302\2474.11's label rule is the first place it bites:");
HERO_STR_STATIC(hero_str_73c5101f, "#     `range`'s two `i64` parameters make its labels mandatory at every call");
HERO_STR_STATIC(hero_str_15194e31, "#     site (panel 028 R1);");
HERO_STR_STATIC(hero_str_21b2ebf7, "#   - a diagnostic raised in this file is a COMPILER BUG, not a user error, and");
HERO_STR_STATIC(hero_str_3038df5b, "#     the pipeline reports it as one.");
HERO_STR_STATIC(hero_str_12bb2714, "# The integers from `from` up to but not including `to`, in order.");
HERO_STR_STATIC(hero_str_3748bf18, "# `to` is excluded, matching `slice(from:, to:)` \342\200\224 the labels and the bound");
HERO_STR_STATIC(hero_str_76442070, "# answer each other, which is why the spec states both on one line.");
HERO_STR_STATIC(hero_str_14a0e224, "# An empty range is not an error: `range(from: 3, to: 3)` and");
HERO_STR_STATIC(hero_str_2d1f7383, "# `range(from: 5, to: 2)` are both `[]`, so a loop over a range that has run out");
HERO_STR_STATIC(hero_str_5198adea, "# runs zero times rather than aborting.");
HERO_STR_STATIC(hero_str_45907265, "function range(from: i64, to: i64) -> [i64]");
HERO_STR_STATIC(hero_str_4c3a7e26, "    out: [i64] @ []");
HERO_STR_STATIC(hero_str_58e970a0, "    i: i64 @ from");
HERO_STR_STATIC(hero_str_63f8113a, "    while i < to");
HERO_STR_STATIC(hero_str_c14b0d2, "        out @ push(out, i)");
HERO_STR_STATIC(hero_str_408b104d, "        i @ i + 1");
HERO_STR_STATIC(hero_str_1ec094de, "    return out");
HERO_STR_STATIC(hero_str_259abb67, "# Each element, transformed. `map(xs, f)` \342\200\224 the signature the spec writes out at");
HERO_STR_STATIC(hero_str_6e617d94, "# line 93, which is why this one needs no explaining.");
HERO_STR_STATIC(hero_str_1a12e62e, "function map<A, B>(xs: [A], f: (function(A) -> B)) -> [B]");
HERO_STR_STATIC(hero_str_2e005a63, "    out: [B] @ []");
HERO_STR_STATIC(hero_str_4f19951e, "    for x in xs");
HERO_STR_STATIC(hero_str_50f186c5, "        out @ push(out, f(x))");
HERO_STR_STATIC(hero_str_380488ea, "# The elements `f` keeps.");
HERO_STR_STATIC(hero_str_64c9bb80, "function filter<A>(xs: [A], f: (function(A) -> bool)) -> [A]");
HERO_STR_STATIC(hero_str_794db558, "    out: [A] @ []");
HERO_STR_STATIC(hero_str_782dae9a, "        if f(x)");
HERO_STR_STATIC(hero_str_6c6b3723, "            out @ push(out, x)");
HERO_STR_STATIC(hero_str_38d77201, "# The elements combined into one value, FROM THE LEFT, with the accumulator");
HERO_STR_STATIC(hero_str_4facae6c, "# passed FIRST \342\200\224 `f(total, x)`, never `f(x, total)`.");
HERO_STR_STATIC(hero_str_5f189747, "# Both of those are decisions the spec now states (panel 029 R6) and this body is");
HERO_STR_STATIC(hero_str_7deb67f4, "# what makes them true. They were undecidable from the spec and the wrong guess");
HERO_STR_STATIC(hero_str_7fc6d27f, "# was SILENT: with an accumulator and an element of the same type \342\200\224 `sum`,");
HERO_STR_STATIC(hero_str_44fe5efb, "# `concat`, `max`, every string builder \342\200\224 either order type-checks and the program");
HERO_STR_STATIC(hero_str_2b9b2692, "# prints a different answer.");
HERO_STR_STATIC(hero_str_13e4e4f9, "function fold<A, B>(xs: [A], start: B, f: (function(acc: B, item: A) -> B)) -> B");
HERO_STR_STATIC(hero_str_2853d45c, "    total: B @ start");
HERO_STR_STATIC(hero_str_7f15e88c, "        total @ f(total, x)");
HERO_STR_STATIC(hero_str_52b255eb, "    return total");
HERO_STR_STATIC(hero_str_f49aad, "# The first element `f` accepts, or an error. `A?` rather than an index, so the");
HERO_STR_STATIC(hero_str_316ca783, "# caller gets the thing rather than a way to look it up again.");
HERO_STR_STATIC(hero_str_1f78dd85, "function find<A>(xs: [A], f: (function(A) -> bool)) -> A?");
HERO_STR_STATIC(hero_str_5d3aeda2, "            return ok(x)");
HERO_STR_STATIC(hero_str_6c48b58d, "    return fail(code: \"not_found\", msg: \"no element satisfies the test\")");
HERO_STR_STATIC(hero_str_414cb39e, "# Does any element pass? Empty is false, which is the same rule as `fold` with a");
HERO_STR_STATIC(hero_str_4bff32b1, "# `false` start.");
HERO_STR_STATIC(hero_str_79d2914a, "function any<A>(xs: [A], f: (function(A) -> bool)) -> bool");
HERO_STR_STATIC(hero_str_3c03efd9, "            return true");
HERO_STR_STATIC(hero_str_5b100fe8, "    return false");
HERO_STR_STATIC(hero_str_1f1d9ce, "# Do all of them? Empty is true \342\200\224 vacuously, and it is the answer that makes");
HERO_STR_STATIC(hero_str_10beac07, "# `all(xs, f) == !any(xs, not_f)` hold at every length.");
HERO_STR_STATIC(hero_str_50c950fa, "function all<A>(xs: [A], f: (function(A) -> bool)) -> bool");
HERO_STR_STATIC(hero_str_4c6836ba, "        if !f(x)");
HERO_STR_STATIC(hero_str_3dfa48cb, "            return false");
HERO_STR_STATIC(hero_str_3d36e98d, "    return true");
HERO_STR_STATIC(hero_str_30171395, "# The program's three edges (\302\2471.11, panel 036). They are HERE, in Heroes, rather");
HERO_STR_STATIC(hero_str_317b1864, "# than in the compiler, and the argument is worth the four lines it takes.");
HERO_STR_STATIC(hero_str_60582202, "# \302\2471.7's test is mechanical: a `T?` is a per-translation-unit generated struct,");
HERO_STR_STATIC(hero_str_2c49bd8f, "# so the C runtime cannot name one and `read_file -> str?` cannot be a runtime");
HERO_STR_STATIC(hero_str_6cf73256, "# entry point without a second composition form in the emitter. Written here it");
HERO_STR_STATIC(hero_str_3e30c462, "# needs none \342\200\224 `ok` and `fail` are the same constructors every other Tier-2");
HERO_STR_STATIC(hero_str_30b02ceb, "# function uses.");
HERO_STR_STATIC(hero_str_450fbd2, "# And the record runs the same way. Pascal predeclared file I/O, command-line");
HERO_STR_STATIC(hero_str_1a932706, "# access and termination; Kernighan's 1981 paper itemises all three as defects;");
HERO_STR_STATIC(hero_str_3807f9d1, "# Oberon predefines none of them; Nim reaches the same ergonomics from an");
HERO_STR_STATIC(hero_str_1f61194e, "# auto-imported module. What crosses to C is only what the language cannot say.");
HERO_STR_STATIC(hero_str_36c288ff, "extern \"hero_os.h\"");
HERO_STR_STATIC(hero_str_4f4811ae, "    # The status codes the wrappers translate, named rather than copied. Before");
HERO_STR_STATIC(hero_str_5a98c574, "    # M-header-constants this file compared `status` against `0`, `1` and `2`, and");
HERO_STR_STATIC(hero_str_2359a0d1, "    # `hero_os.h` says why they were chosen small: *\"small integers rather than");
HERO_STR_STATIC(hero_str_42807cc0, "    # errno\"* \342\200\224 a value picked so a Heroes reader could carry it across by hand.");
HERO_STR_STATIC(hero_str_516d4b1e, "    # Now the header is the only place they are written, and renumbering them there");
HERO_STR_STATIC(hero_str_25ce646, "    # cannot leave this file behind.");
HERO_STR_STATIC(hero_str_245e40c2, "    constant HERO_OS_OK: i64");
HERO_STR_STATIC(hero_str_12cf4abd, "    constant HERO_OS_NOT_FOUND: i64");
HERO_STR_STATIC(hero_str_4ae7fb3, "    constant HERO_OS_NOT_TEXT: i64");
HERO_STR_STATIC(hero_str_13aa2a9, "    function hero_file_read(path: cstr, @status: i64) -> str");
HERO_STR_STATIC(hero_str_64ede056, "    function hero_file_write(path: cstr, text: str) -> i64");
HERO_STR_STATIC(hero_str_3d392cac, "    function hero_args_count() -> i64");
HERO_STR_STATIC(hero_str_68a5e31, "    function hero_args_at(index: i64) -> str");
HERO_STR_STATIC(hero_str_5aede7bf, "    function hero_args_raw(index: i64) -> cstr");
HERO_STR_STATIC(hero_str_7c01798d, "    function hero_exit(code: i64)");
HERO_STR_STATIC(hero_str_3d8e9db7, "extern \"heroes_runtime.h\"");
HERO_STR_STATIC(hero_str_14a3d175, "    # The text conversion that reports instead of dying (panel 089). Its codes");
HERO_STR_STATIC(hero_str_77744eb3, "    # live in the header for the same reason `hero_os.h`'s do, one group up.");
HERO_STR_STATIC(hero_str_18818b8d, "    constant HERO_STR_OK: i64");
HERO_STR_STATIC(hero_str_4f8dcb63, "    function hero_str_try_from_cstr(p: cstr, @status: i64) -> str");
HERO_STR_STATIC(hero_str_4976a076, "# Text that came from C, or the reason it is not text (panel 089, adopting the");
HERO_STR_STATIC(hero_str_31384cbe, "# second-name form panel 059 reserved when it refused `to_str` as the carrier).");
HERO_STR_STATIC(hero_str_35695414, "# It is the ONLY way in. `c.to_str()` used to copy a C string and ABORT on a");
HERO_STR_STATIC(hero_str_49a45288, "# null pointer or on bytes that are not UTF-8 \342\200\224 right for the program's own");
HERO_STR_STATIC(hero_str_2a5b7b1f, "# bytes, wrong for the environment's, and retired at panel 090 for exactly");
HERO_STR_STATIC(hero_str_6cb0fd2c, "# that. A SQLite TEXT column another program wrote, a Latin-1 `PATH`,");
HERO_STR_STATIC(hero_str_6fb132ef, "# an argument the shell handed over: none of those are the program's mistake,");
HERO_STR_STATIC(hero_str_7d3bee51, "# and \302\2471.12 says a Heroes program must not be killed by them. Every language");
HERO_STR_STATIC(hero_str_79c60830, "# whose string carries a UTF-8 invariant ships two names here and none of them");
HERO_STR_STATIC(hero_str_48dba1ea, "# aborts; the one that made this conversion infallible is JNI, and its runtime");
HERO_STR_STATIC(hero_str_d28762e, "# kills the VM instead.");
HERO_STR_STATIC(hero_str_45e19ed2, "# It is a Tier-2 function and not a built-in for \302\2471.7's mechanical reason,");
HERO_STR_STATIC(hero_str_76c5a185, "# which design.md:476-480 already applied to `read_file`: a `T?` is a");
HERO_STR_STATIC(hero_str_4b786308, "# per-translation-unit struct the C runtime cannot name, so the built-in route");
HERO_STR_STATIC(hero_str_4decdfb3, "# costs a second composition arm in the emitter and this route costs zero");
HERO_STR_STATIC(hero_str_31b25b16, "# backend lines.");
HERO_STR_STATIC(hero_str_1bada5cf, "# **The null test is HERE and not in C, and that is the whole trick.** The");
HERO_STR_STATIC(hero_str_32e69926, "# emitter wraps every `cstr` on its way into a C function with a guard that");
HERO_STR_STATIC(hero_str_31ed0ba6, "# aborts on a null pointer, so a C-side `if (p == NULL)` can never run: the");
HERO_STR_STATIC(hero_str_71e9c080, "# guard fires first. Measured \342\200\224 this function's first draft put the test in C");
HERO_STR_STATIC(hero_str_36a0130, "# and died at `panic: a null cstr was passed to a C function`, exit 134, on");
HERO_STR_STATIC(hero_str_8caaec9, "# the very case it exists for. What is closed is asking **C** whether a");
HERO_STR_STATIC(hero_str_6c5da322, "# pointer is null; the language answers that itself with `== nullptr`, so the");
HERO_STR_STATIC(hero_str_4c6426e9, "# question never has to cross (panel 089, compiler-engineer).");
HERO_STR_STATIC(hero_str_67ad976, "function validated(c: cstr) -> str?");
HERO_STR_STATIC(hero_str_74c7f308, "    if c == nullptr");
HERO_STR_STATIC(hero_str_50aee590, "        return fail(code: \"null_cstr\", msg: \"a null `cstr` holds no text\")");
HERO_STR_STATIC(hero_str_6b9fe3fd, "    status: i64 @ 0");
HERO_STR_STATIC(hero_str_328326b8, "    text = hero_str_try_from_cstr(c, @status)");
HERO_STR_STATIC(hero_str_7cbb9991, "    if status == HERO_STR_OK");
HERO_STR_STATIC(hero_str_1e67865a, "        return ok(text)");
HERO_STR_STATIC(hero_str_50d925e8, "    return fail(code: \"not_text\", msg: \"the bytes behind this `cstr` are not UTF-8\")");
HERO_STR_STATIC(hero_str_4a6f7c56, "# The whole file, or an error. The three codes are stable snake_case strings");
HERO_STR_STATIC(hero_str_18986bd4, "# (\302\2474.6), and they are distinguished because a caller almost always wants to:");
HERO_STR_STATIC(hero_str_2cd418d4, "# \"there is no such file\", \"the disk failed\" and \"it read, and it is not text\"");
HERO_STR_STATIC(hero_str_12e1ed52, "# are three program states, and a walk over a directory it did not create");
HERO_STR_STATIC(hero_str_6fab66e0, "# meets all three.");
HERO_STR_STATIC(hero_str_7435dc24, "function read_file(path: str) -> str?");
HERO_STR_STATIC(hero_str_62e17001, "    text = hero_file_read(path.cstr(), @status)");
HERO_STR_STATIC(hero_str_1f200e1, "    if status == HERO_OS_OK");
HERO_STR_STATIC(hero_str_7a29873f, "    if status == HERO_OS_NOT_FOUND");
HERO_STR_STATIC(hero_str_1c190e57, "        return fail(code: \"file_not_found\", msg: \"no file at \" + path)");
HERO_STR_STATIC(hero_str_5076ea5a, "    # The file was there and read whole, and its bytes are not text: the same");
HERO_STR_STATIC(hero_str_39d116e9, "    # code `validated` gives a cstr in that state, because it is the same state.");
HERO_STR_STATIC(hero_str_536b0395, "    # Said `read_failed` until 2026-09-03, which was false \342\200\224 the read succeeded.");
HERO_STR_STATIC(hero_str_50f75a68, "    if status == HERO_OS_NOT_TEXT");
HERO_STR_STATIC(hero_str_70683958, "        return fail(code: \"not_text\", msg: \"the bytes of \" + path + \" are not UTF-8\")");
HERO_STR_STATIC(hero_str_6a9e8415, "    return fail(code: \"read_failed\", msg: \"could not read \" + path)");
HERO_STR_STATIC(hero_str_5ba5504b, "# The text, written whole, replacing whatever was there.");
HERO_STR_STATIC(hero_str_3dc75758, "function write_file(path: str, text: str) -> ()?");
HERO_STR_STATIC(hero_str_4638ce97, "    if hero_file_write(path.cstr(), text) == HERO_OS_OK");
HERO_STR_STATIC(hero_str_359b91a0, "        return ok()");
HERO_STR_STATIC(hero_str_4d19de6a, "    return fail(code: \"write_failed\", msg: \"could not write \" + path)");
HERO_STR_STATIC(hero_str_219113f6, "# The arguments after the program's name \342\200\224 the off-by-one every language's first");
HERO_STR_STATIC(hero_str_97bb4e, "# CLI program gets wrong, answered in the runtime and stated in the spec.");
HERO_STR_STATIC(hero_str_355fb752, "function args() -> [str]");
HERO_STR_STATIC(hero_str_e05e880, "    out: [str] @ []");
HERO_STR_STATIC(hero_str_642f03e8, "    i: i64 @ 0");
HERO_STR_STATIC(hero_str_5ec8b6d7, "    while i < hero_args_count()");
HERO_STR_STATIC(hero_str_5b593d4f, "        out @ push(out, hero_args_at(i))");
HERO_STR_STATIC(hero_str_6c5d2251, "# The same arguments, each one checked \342\200\224 for a program that must survive");
HERO_STR_STATIC(hero_str_65da889d, "# whatever the shell hands it (panel 089).");
HERO_STR_STATIC(hero_str_a33c27b, "# `args()` above ABORTS on an argument that is not UTF-8, and it keeps that");
HERO_STR_STATIC(hero_str_6d378c9d, "# behaviour: it is right for a program that knows its arguments are text, and");
HERO_STR_STATIC(hero_str_255f0bfb, "# twenty programs already use it. This one gives you the failure instead.");
HERO_STR_STATIC(hero_str_4a28f06a, "# **`[str?]` and not `[str]?`, which is the whole design.** One undecodable");
HERO_STR_STATIC(hero_str_27dbbf9, "# argument must not cost a program the other nine: `prog good.txt <bad> more.txt`");
HERO_STR_STATIC(hero_str_5560ed4, "# can report argument 2 and get on with 1 and 3. A fallible ARRAY would throw the");
HERO_STR_STATIC(hero_str_51e5d458, "# good ones away with the bad one, and the position \342\200\224 which argument \342\200\224 is exactly");
HERO_STR_STATIC(hero_str_c3d7843, "# what the program needs to say.");
HERO_STR_STATIC(hero_str_13029c9c, "function args_checked() -> [str?]");
HERO_STR_STATIC(hero_str_41201684, "    out: [str?] @ []");
HERO_STR_STATIC(hero_str_6167ec38, "        out @ push(out, validated(c: hero_args_raw(i)))");
HERO_STR_STATIC(hero_str_152d8226, "# Ends the program with this status. It never returns, and the C function it");
HERO_STR_STATIC(hero_str_5239dd9f, "# calls says so with `_Noreturn` \342\200\224 which is what keeps clang's flow analysis from");
HERO_STR_STATIC(hero_str_35045148, "# treating the code after it as reachable.");
HERO_STR_STATIC(hero_str_5ebc5ce0, "function exit(code: i64)");
HERO_STR_STATIC(hero_str_f64a216, "    hero_exit(code)");
HERO_STR_STATIC(hero_str_2e9b, "[\n");
HERO_STR_STATIC(hero_str_2c, ",");
HERO_STR_STATIC(hero_str_2de248db, "  {\"kind\": \"");
HERO_STR_STATIC(hero_str_fd21998, "\", \"text\": \"");
HERO_STR_STATIC(hero_str_22c8eb4e, "\", \"line\": ");
HERO_STR_STATIC(hero_str_1508abab, ", \"col\": ");
HERO_STR_STATIC(hero_str_7d, "}");
HERO_STR_STATIC(hero_str_2fa1, "]\n");
HERO_STR_STATIC(hero_str_5c, "\\");
HERO_STR_STATIC(hero_str_2f70, "\\\\");
HERO_STR_STATIC(hero_str_22, "\"");
HERO_STR_STATIC(hero_str_2f36, "\\\"");
HERO_STR_STATIC(hero_str_2f82, "\\n");
HERO_STR_STATIC(hero_str_2d732f1e, "t.hero");
HERO_STR_STATIC(hero_str_78e303e2, "error: refusing to format a file with diagnostics");
HERO_STR_STATIC(hero_str_6654b6e8, "error: this is a compiler bug \342\200\224 `");
HERO_STR_STATIC(hero_str_5b704d14, "` was NOT changed");
HERO_STR_STATIC(hero_str_17f9617c, "error: cannot write `");
HERO_STR_STATIC(hero_str_69aa7d26, "`fmt` produced source that does not parse: ");
HERO_STR_STATIC(hero_str_8346013, "`fmt` is not a fixpoint on its own output for `");
HERO_STR_STATIC(hero_str_5860e362, "clean");
HERO_STR_STATIC(hero_str_62173474, "the root file alone does not parse");
HERO_STR_STATIC(hero_str_8b538fd, "`fmt` changed the TREE of `");
HERO_STR_STATIC(hero_str_3b4978e0, "` \342\200\224 the output parses and is a fixpoint, and it is a DIFFERENT PROGRAM");
HERO_STR_STATIC(hero_str_103ac988, "the output parses, is a fixpoint, and holds the same tree");
HERO_STR_STATIC(hero_str_d7e2ec2, "internal error: a diagnostic landed inside the Heroes library, at its line ");
HERO_STR_STATIC(hero_str_f40c5, ": [");
HERO_STR_STATIC(hero_str_2fb7, "] ");
HERO_STR_STATIC(hero_str_561170f4, "nothing to report, carry on");
HERO_STR_STATIC(hero_str_449477f2, "error: cannot write ");
HERO_STR_STATIC(hero_str_427b6f84, "rewrote ");
HERO_STR_STATIC(hero_str_5ef7d632, " unchanged: no `certain` fix applies to its ");
HERO_STR_STATIC(hero_str_6aa67da3, " diagnostic(s)");
HERO_STR_STATIC(hero_str_18dbdfb9, "{\n  \"schema\": 1,\n  \"diagnostics\": [\n");
HERO_STR_STATIC(hero_str_26928e3e, "    {\n");
HERO_STR_STATIC(hero_str_673e85f2, "      \"code\": \"");
HERO_STR_STATIC(hero_str_8fdc0, "\",\n");
HERO_STR_STATIC(hero_str_691b0eb4, "      \"message\": ");
HERO_STR_STATIC(hero_str_168e, ",\n");
HERO_STR_STATIC(hero_str_1172338c, "      \"file\": ");
HERO_STR_STATIC(hero_str_70bd7e6c, "      \"line\": ");
HERO_STR_STATIC(hero_str_536cc885, ",\n      \"col\": ");
HERO_STR_STATIC(hero_str_5907dfbc, "      \"notes\": [");
HERO_STR_STATIC(hero_str_1870d3, "],\n");
HERO_STR_STATIC(hero_str_1fcc8055, "guess");
HERO_STR_STATIC(hero_str_7d07956b, "certain");
HERO_STR_STATIC(hero_str_190a0b82, "{\"title\": ");
HERO_STR_STATIC(hero_str_1c0d7d3c, ", \"replacement\": ");
HERO_STR_STATIC(hero_str_7168b5f5, ", \"certainty\": \"");
HERO_STR_STATIC(hero_str_11e3, "\"}");
HERO_STR_STATIC(hero_str_3878255, "      \"fixes\": [");
HERO_STR_STATIC(hero_str_26928f44, "    }\n");
HERO_STR_STATIC(hero_str_3cff6163, "    },\n");
HERO_STR_STATIC(hero_str_2eb94a6d, "  ]\n}\n");
HERO_STR_STATIC(hero_str_3ef03ae7, "note: ");
HERO_STR_STATIC(hero_str_17ab33c9, " certain fix(es) are in another module and were not applied: ");
HERO_STR_STATIC(hero_str_1957a16, "error: `--dump-ir` and `--emit-c` are both stops \342\200\224 ask for one artifact at a time");
HERO_STR_STATIC(hero_str_4a988508, "wrote ");
HERO_STR_STATIC(hero_str_51124c0, "error: cannot execute ");
HERO_STR_STATIC(hero_str_19cc75a8, "no -o");
HERO_STR_STATIC(hero_str_6a085ea5, "no tests in ");
HERO_STR_STATIC(hero_str_2ad0ee97, "ok   ");
HERO_STR_STATIC(hero_str_5588d31f, "FAIL ");
HERO_STR_STATIC(hero_str_1dd93c5, "tests");
HERO_STR_STATIC(hero_str_27923722, ", all passed");
HERO_STR_STATIC(hero_str_1eb1d78, " failed");
HERO_STR_STATIC(hero_str_42a1ac1, "diagnostics");
HERO_STR_STATIC(hero_str_763d7f5f, "/doctor-out.txt");
HERO_STR_STATIC(hero_str_5e0b445f, "the program is not on this machine");
HERO_STR_STATIC(hero_str_599879f2, "the command could not run");
HERO_STR_STATIC(hero_str_55c6f6d3, "nothing was said");
HERO_STR_STATIC(hero_str_6240f47a, "not found \342\200\224 install a C toolchain");
HERO_STR_STATIC(hero_str_414ad94e, "a version this compiler cannot read");
HERO_STR_STATIC(hero_str_390e8914, "clang ");
HERO_STR_STATIC(hero_str_3c13268e, "clang floor");
HERO_STR_STATIC(hero_str_198fb047, " against a floor of ");
HERO_STR_STATIC(hero_str_5ca189c7, " \342\200\224 the oldest clang this compiler is measured on");
HERO_STR_STATIC(hero_str_149b4a44, "uname");
HERO_STR_STATIC(hero_str_177a, "-s");
HERO_STR_STATIC(hero_str_d93bba2, "unknown");
HERO_STR_STATIC(hero_str_53c126e, "Darwin");
HERO_STR_STATIC(hero_str_6bf7ccd9, "xcode-select");
HERO_STR_STATIC(hero_str_1777, "-p");
HERO_STR_STATIC(hero_str_1989a1e1, "xcode CLT");
HERO_STR_STATIC(hero_str_2c536b33, "not found \342\200\224 run `xcode-select --install`");
HERO_STR_STATIC(hero_str_330c, "cc");
HERO_STR_STATIC(hero_str_71ea14ae, "not found \342\200\224 install a C toolchain (build-essential, base-devel, \342\200\246)");
HERO_STR_STATIC(hero_str_1774, "-m");
HERO_STR_STATIC(hero_str_d1d74ce, "arch");
HERO_STR_STATIC(hero_str_5c08df45, "not found \342\200\224 set HEROES_RUNTIME=<dir>");
HERO_STR_STATIC(hero_str_77572a5e, "/.doctor-probe");
HERO_STR_STATIC(hero_str_3938, "ok");
HERO_STR_STATIC(hero_str_7b6e895a, "cannot write to ");
HERO_STR_STATIC(hero_str_5d9ff6b1, "/ writable");
HERO_STR_STATIC(hero_str_17e601e6, "build cache");
HERO_STR_STATIC(hero_str_9726352, "FAIL");
HERO_STR_STATIC(hero_str_1d47c8, "ok ");
HERO_STR_STATIC(hero_str_1080, "  ");
HERO_STR_STATIC(hero_str_48d7c7ce, "The Zen of Heroes\n\n 1. This language begins with a tribute to David Bowie.\n 2. It is made for language models; people can read it too.\n 3. A model may have read everything; each page must still explain itself.\n 4. What the eye can see is all there is: sound and vision.\n 5. There is one way to say each thing; every program sings in the same voice.\n 6. That way may not be obvious at first; the Starman already knows it.\n 7. The semantics are familiar; the syntax is new.\n 8. Turn and face the strange: every strange choice here is deliberate.\n 9. Nothing changes behind your back; every change signs its name.\n10. Every plausible mistake must become a compile error before the program runs.\n11. Unless you mark the unfinished place with ???.\n12. An honest hole beats a confident guess.\n13. A compile-time error is an answer; a runtime error is an ambush.\n14. An error should tell you how to fix the program. Anything less is a complaint.\n15. Repeating a word is cheap; forgetting one can cost the whole program.\n16. The specification stays small under pressure; every word must earn its place.\n17. Crashes and leaks are bugs. Ashes to ashes: what Heroes takes, it returns.\n18. When pretty code and safe code disagree, safe code wins.\n19. There is no standard library; C is the man who sold the world.\n20. We can be heroes, just for one day.\n");
HERO_STR_STATIC(hero_str_7708a7f0, "heroes \342\200\224 the Heroes compiler\n\nusage: heroes <command> [file] [flags]\n\n");
HERO_STR_STATIC(hero_str_3d01a70e, " <file.hero>");
HERO_STR_STATIC(hero_str_b006e50, " [file]");
HERO_STR_STATIC(hero_str_358cd22b, "\n      ");
HERO_STR_STATIC(hero_str_4474153b, " <path>");
HERO_STR_STATIC(hero_str_26925fc3, "      ");
HERO_STR_STATIC(hero_str_66c37b63, "\n  --version \302\267 --help\n\n");
HERO_STR_STATIC(hero_str_3f2095f9, "streams: the artifact on stdout, diagnostics and progress on stderr.\n");
HERO_STR_STATIC(hero_str_642a774c, "exit:    0 nothing to report \302\267 1 diagnostics were reported, no artifact was produced\n");
HERO_STR_STATIC(hero_str_726678f4, "         2 the tool could not run. `run` forwards the program's own status.\n");
HERO_STR_STATIC(hero_str_1db0a85c, "env:     HEROES_RUNTIME  where heroes_runtime.h and runtime.c live, if not\n");
HERO_STR_STATIC(hero_str_eaa1c49, "         under the working directory or beside the compiler.\n\n");
HERO_STR_STATIC(hero_str_723f7597, "Commands not built yet: lsp \302\267 cc\n");
HERO_STR_STATIC(hero_str_75b5fbc3, "error: cannot read `");
HERO_STR_STATIC(hero_str_4522508, "   (");
HERO_STR_STATIC(hero_str_4cc9efa0, " ranks)");
HERO_STR_STATIC(hero_str_5ccf48d, "maximum");
HERO_STR_STATIC(hero_str_1c36bf7d, "   a lower bound, not the reader's tokeniser");
HERO_STR_STATIC(hero_str_39cee3d4, "spread");
HERO_STR_STATIC(hero_str_25b820a4, "   between the two vendored tables (");
HERO_STR_STATIC(hero_str_e3f6c6b, "%) \342\200\224 the gap between two REAL tokeniser generations was 967");
HERO_STR_STATIC(hero_str_5c34e23c, "STALE: the recorded count is for ");
HERO_STR_STATIC(hero_str_59255b4a, " and this file is ");
HERO_STR_STATIC(hero_str_2e, ".");
HERO_STR_STATIC(hero_str_1b9dd332, "Run `heroes measure ");
HERO_STR_STATIC(hero_str_2a978d, " --refresh` and paste what it prints.");
HERO_STR_STATIC(hero_str_7668873b, "No verdict is given against a stale count: that is the sentence that");
HERO_STR_STATIC(hero_str_2baac79d, "spent 998 tokens nobody had (docs/measurements/023).");
HERO_STR_STATIC(hero_str_f6133a2, "real");
HERO_STR_STATIC(hero_str_871a0, "   ");
HERO_STR_STATIC(hero_str_29e9670d, " \342\200\224 the binding number");
HERO_STR_STATIC(hero_str_549239f5, "STALE: the recorded real count was taken when the vendored reading was");
HERO_STR_STATIC(hero_str_20234a21, " and it is ");
HERO_STR_STATIC(hero_str_a6cad84, " now, ");
HERO_STR_STATIC(hero_str_1e7f1f50, " away against a window of ");
HERO_STR_STATIC(hero_str_2a978b, " --refresh` and paste what it prints,");
HERO_STR_STATIC(hero_str_30b6e74b, "and say in the commit body what was added and what paid for it \342\200\224 a rule");
HERO_STR_STATIC(hero_str_465c03ab, "moved into .claude/rules/, into the case law, or into a skill.");
HERO_STR_STATIC(hero_str_5fceed16, "The ceiling watches the LEVEL and this watches the MOVEMENT: it bounds");
HERO_STR_STATIC(hero_str_231376e9, "attribution rather than size, so every increase carries a name (panel 134).");
HERO_STR_STATIC(hero_str_52230a47, "No ceiling judges `");
HERO_STR_STATIC(hero_str_41489909, "` and no check keeps it honest");
HERO_STR_STATIC(hero_str_2a18082d, "(panel 123 R5), so this is a count and not a verdict.");
HERO_STR_STATIC(hero_str_62e135a1, "The two documents that are judged are `");
HERO_STR_STATIC(hero_str_69110222, "` and `");
HERO_STR_STATIC(hero_str_314e, "`.");
HERO_STR_STATIC(hero_str_735bc850, "BREACH: ");
HERO_STR_STATIC(hero_str_678712f1, " over the ");
HERO_STR_STATIC(hero_str_6444bec9, "-token ceiling (design.md \302\2471.6).");
HERO_STR_STATIC(hero_str_2a59cd61, "An amendment must be net-negative, or the ceiling moves \342\200\224 with a");
HERO_STR_STATIC(hero_str_3607815c, "measurement, a panel, and a named alternative (panel 012).");
HERO_STR_STATIC(hero_str_647a5e1d, "An addition needs a named removal or a pre-registered falsifiable");
HERO_STR_STATIC(hero_str_22980fc9, "prediction (panel 012). ");
HERO_STR_STATIC(hero_str_7af243a1, "claude-legacy");
HERO_STR_STATIC(hero_str_aa7aa93, "cl100k_base");
HERO_STR_STATIC(hero_str_70921616, "spec/heroes-spec.md");
HERO_STR_STATIC(hero_str_e26a397, "unused");
HERO_STR_STATIC(hero_str_3c921d75, "plain");
HERO_STR_STATIC(hero_str_2652efaa, "examples");
HERO_STR_STATIC(hero_str_78438baf, "error: no operator `");
HERO_STR_STATIC(hero_str_8cce658, "`\n  the ");
HERO_STR_STATIC(hero_str_269ca4be, " are: ");
HERO_STR_STATIC(hero_str_74e2afb1, "error: no `.hero` files under ");
HERO_STR_STATIC(hero_str_4655a35e, "corpus: ");
HERO_STR_STATIC(hero_str_716c0ac5, " programs under ");
HERO_STR_STATIC(hero_str_13ab0ca5, "no_corpus");
HERO_STR_STATIC(hero_str_3580f6de, ".hero");
HERO_STR_STATIC(hero_str_7d99834b, "every program compiles");
HERO_STR_STATIC(hero_str_452bbd46, "this corpus does not compile, so its kill rate would be meaningless\n  ");
HERO_STR_STATIC(hero_str_466f899, " of ");
HERO_STR_STATIC(hero_str_26738cc6, " programs are already refused by `heroes check`:\n");
HERO_STR_STATIC(hero_str_4522500, "    ");
HERO_STR_STATIC(hero_str_7042178b, "  every mutant of a program that is already wrong is killed by the\n  diagnostic that was already there \342\200\224 run `heroes check` on each");
HERO_STR_STATIC(hero_str_46dbcb10, "Heroes: the terminals and the precedence, read from the compiler's own tables.\n\n");
HERO_STR_STATIC(hero_str_528, "\n\n");
HERO_STR_STATIC(hero_str_275e9aaf, "Keywords (");
HERO_STR_STATIC(hero_str_c080db1, "), which a program may not use as a name:");
HERO_STR_STATIC(hero_str_2aeda, "\n  ");
HERO_STR_STATIC(hero_str_5dba8d57, "Binary operators, loosest first. Every one is left-associative, so the\nclimber asks for `power + 1` on the right. The `operator` column is the name\nthe tree carries, and a spelling paired with the wrong one parses as the wrong\noperator with every test green (panel 067).\n");
HERO_STR_STATIC(hero_str_1dcd4e6d, "\n  power  spelling  operator");
HERO_STR_STATIC(hero_str_6278e1a6, " IS IN THE LIST AND NOT IN THE TABLE");
HERO_STR_STATIC(hero_str_4b79326b, "The productions are in `");
HERO_STR_STATIC(hero_str_7a260b80, "`, which is not readable from here.\nThis command reads it relative to the working directory, as `measure` reads its\ntables, so run it from the repository to see them collected.");
HERO_STR_STATIC(hero_str_3b27f5fe, "Productions, collected from `");
HERO_STR_STATIC(hero_str_32474f85, "`, where each is authored beside the\nprose that governs it. `=` defines and `.` ends, `|` alternates, `[ ]` is\noptional, `{ }` repeats zero or more times.");
HERO_STR_STATIC(hero_str_5db5ff2e, "Not here, because the compiler holds no table to print it from: the six\ncontextual words \342\200\224 `as`, `link`, `package`, `tag`, `partial`, `owned` \342\200\224 which\nare ordinary identifiers everywhere except the one position each is read in.\n\nAnd nothing above is checked against the parser. The keywords and the powers\nare read from the compiler's own tables, so they cannot drift from it; the\nproductions are checked for internal consistency only, which is `ebnflint`'s\nclass and Go's. No instrument compares a production to the function that reads\nit.");
